/**
 * The prompt bodies PlanMo installs as agent commands.
 *
 * A template never asks the agent to write plan documents itself. The agent runs
 * the CLI, reads the plan PlanMo emitted, does the work, and — only if asked —
 * proposes deltas that PlanMo validates before anything changes. PlanMo owns
 * every generated byte, so the output stays deterministic and reviewable.
 *
 * Keep these short and mechanical. A template that needs per-agent wording is a
 * sign it is doing too much.
 */
export interface AgentCommandTemplate {
  /** Command name without the prefix, e.g. `next` -> `planmo-next`. */
  name: string;
  /** One-line description for the agent's command list (<= 1024 chars, single line). */
  description: string;
  /** The prompt body written into the command file. */
  body: string;
}

/** Every command PlanMo installs, in deterministic order. */
export const AGENT_COMMANDS: readonly AgentCommandTemplate[] = [
  {
    name: 'next',
    description: 'Show the next PlanMo task and the context to work it.',
    body: [
      'Run `npx planmo next --print` and follow the directive it prints.',
      '',
      'Read the files it names before changing anything. Respect the task scope:',
      'change only what the task requires, and add no adjacent edits.',
      '',
      'When you are done, run `npx planmo validate` and report its exact output.',
    ].join('\n'),
  },
  {
    name: 'status',
    description: 'Report PlanMo workspace health.',
    body: [
      'Run `npx planmo status` and `npx planmo validate`, then summarize what they',
      'report. Do not change any file for this command.',
    ].join('\n'),
  },
  {
    name: 'propose',
    description: 'Propose a plan change for PlanMo to validate and apply.',
    body: [
      'Read `planning/MASTER-PLAN.md`, `planning/CONTEXT.md` and `planning/tasks.csv`.',
      '',
      'Then produce ONE JSON document and nothing else — no prose around it:',
      '',
      '```json',
      '{',
      '  "schemaVersion": 1,',
      '  "agent": "<your agent id>",',
      '  "requestId": "<what you were asked>",',
      '  "items": [{ "id": "<stable-id>", "summary": "<what should change and why>" }]',
      '}',
      '```',
      '',
      'Proposed changes are DELTAS, not commands. Do not edit any project file',
      'yourself: save the JSON as `proposal.json` and tell the user to run',
      '`npx planmo agent apply proposal.json`, which validates it before anything',
      'changes.',
    ].join('\n'),
  },
];
